// Generated by scripts/make_ts_types.py from scanner/models.py and backend/jobs.py.
// Do not edit: change the Pydantic models, then run `python -m scripts.make_ts_types`.

export type Severity = "critical" | "high" | "medium" | "low" | "info";
export type Confidence = "high" | "medium" | "low";
export type Scope = "line" | "file" | "project";
export type ScanState = "queued" | "running" | "done" | "failed";
export type ScanSource = "zip" | "git";

/** Most severe first, the order used everywhere in the UI. */
export const SEVERITIES = ["critical", "high", "medium", "low", "info"] as const satisfies readonly Severity[];
export const CONFIDENCES = ["high", "medium", "low"] as const satisfies readonly Confidence[];
export const DISCLAIMER = "Legal mapping is indicative, not legal advice.";

/**
 * Masked source lines around a finding, for the code viewer. Needed because uploads
 * are deleted after the scan, so the frontend cannot fetch the file later.
 */
export interface Context {
  start_line: number;
  lines: string[];
}

/**
 * What the scan looked at, so a reader knows what "no findings" means.
 */
export interface Coverage {
  files_by_kind: Record<string, number>;
  rules_checked: string[];
  rules_not_checked: string[];
}

/**
 * A Hit plus the legal meaning of its rule: one entry in report.json.
 */
export interface Finding {
  id: string;
  rule_id: string;
  title: string;
  category: string;
  scope: Scope;
  file: string | null;
  line: number | null;
  evidence: string;
  context: Context | null;
  pii: string[];
  confidence: Confidence;
  law: Law;
  penalty: PenaltyCap;
  severity: Severity;
  severity_reason: string;
  fix: string;
}

/**
 * Where an obligation comes from. Same shape in the rules YAML and in a Finding.
 */
export interface Law {
  act: string[];
  rules: string[];
  requirement: string;
}

/**
 * One entry of the penalty Schedule to the Act (s.33).
 */
export interface PenaltyCap {
  schedule_item: number;
  provision: string;
  cap: string;
}

/**
 * The master output format (report.json). HTML, PDF and SARIF are made from it.
 */
export interface Report {
  tool: string;
  tool_version: string;
  rules_version: string;
  target: string;
  generated_at: string;
  files_scanned: number;
  coverage: Coverage | null;
  disclaimer: string;
  summary: Summary;
  findings: Finding[];
}

/**
 * Response of POST /api/scan. `delete_token` is shown once: whoever holds it can delete
 * the scan early (DELETE /api/scans/{id}); it is never part of any other response.
 */
export interface ScanStarted {
  scan_id: string;
  delete_token: string;
}

/**
 * Response of GET /api/scan/{id}: never paths, never raw evidence. `steps` lists every
 * step of this kind of scan in order; `step` is the current one, or the one that failed.
 */
export interface ScanStatus {
  scan_id: string;
  target: string;
  source: ScanSource;
  status: ScanState;
  step: string;
  steps: string[];
  created_at: string;
  expires_at: string;
  finished_at: string | null;
  error: string | null;
  summary: Summary | null;
}

/**
 * Counts for the dashboard tiles and charts. Always recomputed from the findings.
 */
export interface Summary {
  total: number;
  by_severity: Record<Severity, number>;
  by_category: Record<string, number>;
  by_provision: Record<string, number>;
}
